<input class="sl-in mono" id="ac-otp-code" inputmode="numeric" maxlength="6" placeholder="6 digits" style="font-size:22px;letter-spacing:.3em;text-align:center"><div class="sl-banner" id="ac-otp-msg" style="display:none"></div>
<div class="row g8 wrap"><button class="sl-btn" type="button" id="ac-otp-ok"><i class="ic ic-sm i-check" aria-hidden="true"></i>Verify</button><button class="sl-btn ghost" type="button" id="ac-otp-resend">Resend code</button><button class="sl-btn ghost" type="button" id="ac-otp-cancel" style="color:var(--red-ink)">Discard account</button></div></div></div>
<script>
(function () {
  var f = document.getElementById('ac-form'), dlg = document.getElementById('ac-otp'), msg = document.getElementById('ac-otp-msg');
  function note(t, bad) { msg.style.display = ''; msg.textContent = t; msg.className = 'sl-banner ' + (bad ? 'bad' : 'info'); }
  document.getElementById('ac-gen').addEventListener('click', function () { var c = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789', s = ''; var a = new Uint32Array(12); crypto.getRandomValues(a); a.forEach(function (n) { s += c[n % c.length]; }); document.getElementById('ac-pw').value = s; });
  function send() { return SL.post('ajax/customers/client_otp_send_ajax.php', {}).then(function (j) { if (j.ok) note('Code sent to ' + (j.email || 'the customer')); else note(j.error || 'Could not send the code', true); }); }
  f.addEventListener('submit', function (e) {
    e.preventDefault(); var btn = document.querySelector('[form="ac-form"]'); btn.disabled = true;
    f.querySelectorAll('.sl-err').forEach(function (x) { x.remove(); });
    SL.post('ajax/customers/customers_add_ajax.php', new FormData(f)).then(function (j) {
      if (j.status === 'success') { SL.toast(j.message || 'Customer created'); setTimeout(function () { location.href = '<?= sl_route('Customers') ?>'; }, 500); return; }
      if (j.status === 'verify') { document.getElementById('ac-otp-mail').textContent = j.email || ''; dlg.hidden = false; send(); return; }
      SL.toast(j.message || 'Please check the form', true);
    }).catch(function () { SL.toast('Network error', true); }).finally(function () { btn.disabled = false; });
  });
  document.getElementById('ac-otp-resend').addEventListener('click', send);
  document.getElementById('ac-otp-ok').addEventListener('click', function () {
    SL.post('ajax/customers/client_otp_verify_ajax.php', { otp_code: document.getElementById('ac-otp-code').value }).then(function (j) {
      if (j.ok) { SL.toast('E-mail verified, customer created'); setTimeout(function () { location.href = '<?= sl_route('Customers') ?>'; }, 500); } else note(j.error || 'Wrong code', true);
    });
  });
  document.getElementById('ac-otp-cancel').addEventListener('click', function () {
    if (!confirm('Discard the new account?')) return;
    SL.post('ajax/customers/client_otp_discard_ajax.php', {}).then(function () { dlg.hidden = true; SL.toast('Account discarded'); });
  });
})();
</script>
<?php else: ?>
